import boto3
import json
from flask import Flask, request, jsonify, session

app = Flask(__name__)
app.secret_key = 'pipeline-secret-key-2024'

# CI/CD Pipeline Plugin - Artifact Deployment Manager
# Allows pipeline users to manage deployment artifacts and trigger deployments

def get_s3_client():
    return boto3.client('s3', region_name='us-east-1')

def get_iam_client():
    return boto3.client('iam', region_name='us-east-1')

@app.route('/api/pipeline/artifacts/<pipeline_id>', methods=['GET'])
def list_artifacts(pipeline_id):
    """List artifacts for a given pipeline - no ownership check"""
    s3 = get_s3_client()
    prefix = f"pipelines/{pipeline_id}/artifacts/"
    response = s3.list_objects_v2(Bucket='ci-cd-artifacts-prod', Prefix=prefix)
    artifacts = [obj['Key'] for obj in response.get('Contents', [])]
    return jsonify({'pipeline_id': pipeline_id, 'artifacts': artifacts})

@app.route('/api/pipeline/deploy', methods=['POST'])
def trigger_deployment():
    """Trigger deployment for any pipeline - IDOR vulnerability"""
    data = request.get_json()
    pipeline_id = data.get('pipeline_id')
    target_env = data.get('target_environment', 'staging')
    artifact_key = data.get('artifact_key')

    # No authorization check - any authenticated user can deploy any pipeline's artifacts
    # to any environment including production

    s3 = get_s3_client()

    # Copy artifact to deployment bucket
    copy_source = {'Bucket': 'ci-cd-artifacts-prod', 'Key': artifact_key}
    dest_key = f"deployments/{target_env}/{pipeline_id}/{artifact_key.split('/')[-1]}"

    s3.copy_object(
        CopySource=copy_source,
        Bucket='deployment-targets-prod',
        Key=dest_key
    )

    return jsonify({'status': 'deployed', 'target': target_env, 'key': dest_key})

@app.route('/api/pipeline/config/<pipeline_id>', methods=['GET'])
def get_pipeline_config(pipeline_id):
    """Retrieve pipeline configuration including secrets - IDOR"""
    s3 = get_s3_client()
    # Direct object reference without ownership validation
    config_key = f"pipelines/{pipeline_id}/config/pipeline.json"
    response = s3.get_object(Bucket='ci-cd-artifacts-prod', Key=config_key)
    config = json.loads(response['Body'].read().decode('utf-8'))
    return jsonify(config)

@app.route('/api/pipeline/config/<pipeline_id>', methods=['PUT'])
def update_pipeline_config(pipeline_id):
    """Update pipeline config - allows modifying other teams' pipelines"""
    data = request.get_json()
    s3 = get_s3_client()
    config_key = f"pipelines/{pipeline_id}/config/pipeline.json"

    s3.put_object(
        Bucket='ci-cd-artifacts-prod',
        Key=config_key,
        Body=json.dumps(data),
        ContentType='application/json'
    )
    return jsonify({'status': 'updated', 'pipeline_id': pipeline_id})

@app.route('/api/pipeline/role/<pipeline_id>', methods=['POST'])
def assume_pipeline_role(pipeline_id):
    """Assume the execution role of any pipeline - IDOR to privilege escalation"""
    sts = boto3.client('sts', region_name='us-east-1')
    role_arn = f"arn:aws:iam::123456789012:role/pipeline-exec-{pipeline_id}"

    # No check that the requesting user owns this pipeline
    response = sts.assume_role(
        RoleArn=role_arn,
        RoleSessionName=f"deploy-session-{pipeline_id}",
        DurationSeconds=3600
    )

    credentials = response['Credentials']
    return jsonify({
        'access_key': credentials['AccessKeyId'],
        'secret_key': credentials['SecretAccessKey'],
        'session_token': credentials['SessionToken'],
        'expiration': str(credentials['Expiration'])
    })

@app.route('/api/pipeline/webhook/<pipeline_id>', methods=['POST'])
def configure_webhook(pipeline_id):
    """Set deployment webhook URL for pipeline notifications"""
    data = request.get_json()
    webhook_url = data.get('webhook_url')
    s3 = get_s3_client()

    webhook_config = {'pipeline_id': pipeline_id, 'webhook_url': webhook_url}
    s3.put_object(
        Bucket='ci-cd-artifacts-prod',
        Key=f"pipelines/{pipeline_id}/webhooks/notify.json",
        Body=json.dumps(webhook_config),
        ContentType='application/json'
    )
    return jsonify({'status': 'webhook_configured'})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
